fn add(rows:&mut usize,count:usize,maximum:usize)->Result<(),ValueError>{*rows=rows.checked_add(count).filter(|n|*n<=maximum).ok_or_else(||invalid("grid3d native rows exceed caller limit"))?;Ok(())}
