//! 🧱️ Complete authored Grid3d cells admitted from borrowed records before typed ownership.
use super::*;
use semio_framework_dsl_record::{FieldValue,RecordValue};
use semio_framework_value::{NativeDecodeControl,ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,artifact::{Cell,RowWriter}};
fn invalid(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn unwrap(value:&FieldValue)->&FieldValue{match value{FieldValue::Block(value)=>value,_=>value}}
fn field(record:&RecordValue,id:u16)->Option<&FieldValue>{record.get(id).map(unwrap)}
fn text(record:&RecordValue,id:u16)->Result<&str,ValueError>{match field(record,id){Some(FieldValue::Text(value))=>Ok(value),_=>Err(invalid("grid3d literal native text differs"))}}
fn uint(record:&RecordValue,id:u16,default:u64)->Result<u64,ValueError>{match field(record,id){Some(FieldValue::UInt(value))=>Ok(*value),None|Some(FieldValue::Absent)=>Ok(default),_=>Err(invalid("grid3d native unsigned value differs"))}}
fn boolean(record:&RecordValue,id:u16)->Result<bool,ValueError>{match field(record,id){Some(FieldValue::Bool(value))=>Ok(*value),None|Some(FieldValue::Absent)=>Ok(false),_=>Err(invalid("grid3d native flag differs"))}}
fn list(record:&RecordValue,id:u16)->Result<&[FieldValue],ValueError>{match field(record,id){Some(FieldValue::List(items))=>Ok(items),None|Some(FieldValue::Absent)=>Ok(&[]),_=>Err(invalid("grid3d native collection shape differs"))}}
fn record(value:&FieldValue)->Result<&RecordValue,ValueError>{match unwrap(value){FieldValue::Record(value)=>Ok(value),_=>Err(invalid("grid3d native record shape differs"))}}
fn nested(recordValue:&RecordValue,id:u16)->Result<&RecordValue,ValueError>{record(recordValue.get(id).ok_or_else(||invalid("grid3d native nested record absent"))?)}
fn scalar(value:&FieldValue)->Result<f64,ValueError>{match unwrap(value){FieldValue::Float(value)=>Ok(*value),_=>Err(invalid("grid3d native IEEE value differs"))}}
fn word(record:&RecordValue,id:u16)->Result<i64,ValueError>{let value=uint(record,id,0)?;Ok(i64::from(u32::try_from(value).map_err(|_|invalid("grid3d native unsigned32 differs"))?))}
fn seed(mut value:u64,buffer:&mut[u8;20])->&str{let mut start=20;loop{start-=1;buffer[start]=b'0'+(value%10)as u8;value/=10;if value==0{break}}std::str::from_utf8(&buffer[start..]).expect("decimal digits")}
fn write_record(root:&RecordValue,p:&mut RowWriter<'_,'_>)->Result<(),ValueError>{
 let mut decimal=[0u8;20];let schema=match field(root,0){Some(FieldValue::Text(value))=>value.as_str(),None|Some(FieldValue::Absent)=>WFC_GRID3D_DOCUMENT_SCHEMA,_=>return Err(invalid("grid3d native schema differs"))};
 p.insert_key("wfc_grid3d_document",1,&[Cell::Text(schema),Cell::Text(seed(uint(root,1,0)?,&mut decimal)),Cell::Integer(word(root,2)?),Cell::Integer(word(root,3)?),Cell::Integer(word(root,4)?),Cell::Integer(i64::from(boolean(root,8)?)),Cell::Integer(i64::from(boolean(root,9)?)),Cell::Integer(i64::from(boolean(root,10)?))])?;
 for(axis,id)in[("x",5),("y",6),("z",7)]{for(i,value)in list(root,id)?.iter().enumerate(){p.insert_float("wfc_grid3d_cell_size",&[Cell::Integer(1),Cell::Text(axis),Cell::Integer(sqlite::number(i)?),Cell::Real(scalar(value)?)],sqlite::columns("wfc_grid3d_cell_size"))?;}}
 for(i,value)in list(root,11)?.iter().enumerate(){
  let tile=record(value)?;let media=field(tile,3).ok_or_else(||invalid("grid3d native tile media absent"))?;let FieldValue::Statements(items)=media else{return Err(invalid("grid3d native tile media shape differs"))};let[(kind,variant)]=items.as_slice()else{return Err(invalid("grid3d native tile media arity differs"))};let literal=match kind.as_str(){"mesh"=>"mesh","mesh-child"=>"mesh_child",_=>return Err(invalid("grid3d native tile media tag differs"))};
  let label=match field(tile,1){Some(FieldValue::Text(value))=>Cell::Text(value),None|Some(FieldValue::Absent)=>Cell::Null,_=>return Err(invalid("grid3d native tile label differs"))};
  let weight=scalar(tile.get(2).ok_or_else(||invalid("grid3d native tile weight absent"))?)?;
  let id=p.insert_float("wfc_grid3d_tile",&[Cell::Integer(1),Cell::Integer(sqlite::number(i)?),Cell::Text(text(tile,0)?),label,Cell::Real(weight),Cell::Text(literal)],sqlite::columns("wfc_grid3d_tile"))?;
  match kind.as_str(){"mesh"=>{let mesh=nested(variant,0)?;p.insert_key("wfc_grid3d_mesh",id,&[])?;
   for(i,v)in list(mesh,0)?.iter().enumerate(){p.insert_float("wfc_grid3d_position",&[Cell::Integer(id),Cell::Integer(sqlite::number(i)?),Cell::Real(scalar(v)?)],sqlite::columns("wfc_grid3d_position"))?;}
   for(i,v)in list(mesh,1)?.iter().enumerate(){let FieldValue::UInt(value)=unwrap(v)else{return Err(invalid("grid3d native mesh index differs"))};let value=u32::try_from(*value).map_err(|_|invalid("grid3d native mesh index exceeds unsigned32"))?;p.insert("wfc_grid3d_index",&[Cell::Integer(id),Cell::Integer(sqlite::number(i)?),Cell::Integer(i64::from(value))])?;}
   match field(mesh,2){None|Some(FieldValue::Absent)=>{},Some(value)=>{let color=record(value)?;p.insert_key("wfc_grid3d_color",id,&[Cell::Integer(word(color,0)?),Cell::Integer(word(color,1)?),Cell::Integer(word(color,2)?),Cell::Integer(word(color,3)?)])?;}}
  },"mesh-child"=>{let child=nested(variant,0)?;let target=nested(child,1)?;p.insert_key("wfc_grid3d_mesh_child",id,&[Cell::Text(text(child,0)?),Cell::Text(text(target,0)?),Cell::Text(text(target,1)?),Cell::Text(text(target,2)?),Cell::Text(text(target,3)?)])?;},_=>unreachable!()}
 }
 for(i,value)in list(root,12)?.iter().enumerate(){let rule=record(value)?;let direction=match field(rule,3){Some(FieldValue::Enum(index))=>match index{0=>"LEFT",1=>"RIGHT",2=>"FRONT",3=>"BACK",4=>"BOTTOM",5=>"TOP",_=>return Err(invalid("grid3d native direction differs"))},_=>return Err(invalid("grid3d native direction shape differs"))};p.insert("wfc_grid3d_rule",&[Cell::Integer(1),Cell::Integer(sqlite::number(i)?),Cell::Text(text(rule,0)?),Cell::Text(text(rule,1)?),Cell::Text(text(rule,2)?),Cell::Text(direction),Cell::Integer(i64::from(boolean(rule,4)?))])?;}
 for(i,value)in list(root,13)?.iter().enumerate(){let pin=record(value)?;p.insert("wfc_grid3d_pin",&[Cell::Integer(1),Cell::Integer(sqlite::number(i)?),Cell::Integer(word(pin,0)?),Cell::Integer(word(pin,1)?),Cell::Integer(word(pin,2)?),Cell::Text(text(pin,3)?)])?;}
 for(i,value)in list(root,14)?.iter().enumerate(){let mask=record(value)?;p.insert("wfc_grid3d_mask",&[Cell::Integer(1),Cell::Integer(sqlite::number(i)?),Cell::Integer(word(mask,0)?),Cell::Integer(word(mask,1)?),Cell::Integer(word(mask,2)?)])?;}Ok(())
}
fn admit_record(record:&RecordValue,native:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{native.scoped_stage(|native|{native.begin_stage(0)?;let mut completed=0;let mut progress=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{let delta=event.completed.saturating_sub(completed);completed=event.completed;native.advance(delta).is_ok()};let mut control=SqliteSnapshotControl::new(&mut progress,limits);let mut writer=RowWriter::borrowed(&mut control,SqliteSnapshotPhase::DecodeNative)?;write_record(record,&mut writer)?;writer.finish_borrowed()})}
pub(crate)fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,c:&mut SqliteSnapshotControl<'_>)->Result<Grid3dSnapshot,ValueError>{sqlite::authored_schema(c)?;let limits=c.limits();store::decode_sqlite_snapshot_record_native(payload,<Grid3dSnapshot as store::ArtifactDsl>::envelope_id(),Grid3dSnapshot::__dsl_spec_producer(),|record,native|{admit_record(record,native,limits)?;Grid3dSnapshot::__dsl_from_record_controlled(record,native)},c)}
pub(crate)fn encode_sqlite_snapshot_native(value:&Grid3dSnapshot,encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{sqlite::semantic(value,SqliteSnapshotPhase::EncodeNative,c)?;store::encode_sqlite_snapshot_record_native(encoding,<Grid3dSnapshot as store::ArtifactDsl>::envelope_id(),Grid3dSnapshot::__dsl_spec_producer(),|native|value.__dsl_to_record_controlled(native),c)}
